window.ScripturaLexicons.BDAG_PART_0208 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-01\" data-source=\"BDAG\" data-search=\"κορβᾶν substantivo indeclinável; empréstimo hebraico corbã; oferta consagrada a Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κορβᾶν</td><td>substantivo indeclinável; empréstimo hebraico</td><td>corbã; oferta consagrada a Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-02\" data-source=\"BDAG\" data-search=\"κορβανᾶς, ᾶ, ὁ substantivo masculino; empréstimo semítico tesouro do templo; tesouraria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κορβανᾶς, ᾶ, ὁ</td><td>substantivo masculino; empréstimo semítico</td><td>tesouro do templo; tesouraria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-03\" data-source=\"BDAG\" data-search=\"Κόρε, ὁ nome próprio masculino indeclinável Corá; líder de uma rebelião contra Moisés BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κόρε, ὁ</td><td>nome próprio masculino indeclinável</td><td>Corá; líder de uma rebelião contra Moisés</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-04\" data-source=\"BDAG\" data-search=\"κορέννυμι verbo saciar; fartar-se; ficar satisfeito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κορέννυμι</td><td>verbo</td><td>saciar; fartar-se; ficar satisfeito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-05\" data-source=\"BDAG\" data-search=\"κόρη, ης, ἡ substantivo feminino pupila do olho; menina; jovem mulher BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόρη, ης, ἡ</td><td>substantivo feminino</td><td>pupila do olho; menina; jovem mulher</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-06\" data-source=\"BDAG\" data-search=\"Κορίνθιος, ου, ὁ substantivo masculino; gentílico coríntio; habitante de Corinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κορίνθιος, ου, ὁ</td><td>substantivo masculino; gentílico</td><td>coríntio; habitante de Corinto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-07\" data-source=\"BDAG\" data-search=\"Κόρινθος, ου, ἡ nome próprio geográfico feminino Corinto; cidade grega e capital da Acaia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κόρινθος, ου, ἡ</td><td>nome próprio geográfico feminino</td><td>Corinto; cidade grega e capital da Acaia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-08\" data-source=\"BDAG\" data-search=\"Κορνήλιος, ου, ὁ nome próprio masculino Cornélio; centurião romano de Cesareia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κορνήλιος, ου, ὁ</td><td>nome próprio masculino</td><td>Cornélio; centurião romano de Cesareia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-09\" data-source=\"BDAG\" data-search=\"κόρος, ου, ὁ substantivo masculino; unidade de medida coro; medida hebraica de capacidade para secos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόρος, ου, ὁ</td><td>substantivo masculino; unidade de medida</td><td>coro; medida hebraica de capacidade para secos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-10\" data-source=\"BDAG\" data-search=\"κοσμέω verbo ordenar; arrumar; adornar; embelezar; honrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμέω</td><td>verbo</td><td>ordenar; arrumar; adornar; embelezar; honrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-11\" data-source=\"BDAG\" data-search=\"κοσμικός, ή, όν adjetivo terreno; mundano; relativo ao mundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμικός, ή, όν</td><td>adjetivo</td><td>terreno; mundano; relativo ao mundo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-12\" data-source=\"BDAG\" data-search=\"κόσμιος, (ία), ον adjetivo respeitável; honrado; decoroso; apropriado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόσμιος, (ία), ον</td><td>adjetivo</td><td>respeitável; honrado; decoroso; apropriado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-13\" data-source=\"BDAG\" data-search=\"κοσμίως advérbio decorosamente; com modéstia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμίως</td><td>advérbio</td><td>decorosamente; com modéstia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-14\" data-source=\"BDAG\" data-search=\"κοσμοκράτωρ, ορος, ὁ substantivo masculino governante do mundo; dominador deste mundo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμοκράτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>governante do mundo; dominador deste mundo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-15\" data-source=\"BDAG\" data-search=\"κοσμοπλανής, ῆτος, ὁ substantivo masculino enganador do mundo; sedutor universal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμοπλανής, ῆτος, ὁ</td><td>substantivo masculino</td><td>enganador do mundo; sedutor universal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-16\" data-source=\"BDAG\" data-search=\"κοσμοπλάνος remissão lexical veja κοσμοπλανής BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κοσμοπλάνος</td><td>remissão lexical</td><td>veja κοσμοπλανής</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-17\" data-source=\"BDAG\" data-search=\"κόσμος, ου, ὁ substantivo masculino adorno; ordem; universo; Terra; humanidade; mundo; totalidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κόσμος, ου, ὁ</td><td>substantivo masculino</td><td>adorno; ordem; universo; Terra; humanidade; mundo; totalidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-18\" data-source=\"BDAG\" data-search=\"Κούαρτος, ου, ὁ nome próprio masculino Quarto; cristão mencionado por Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κούαρτος, ου, ὁ</td><td>nome próprio masculino</td><td>Quarto; cristão mencionado por Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-19\" data-source=\"BDAG\" data-search=\"κουμ forma aramaica; imperativo levanta-te; põe-te de pé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κουμ</td><td>forma aramaica; imperativo</td><td>levanta-te; põe-te de pé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0208-20\" data-source=\"BDAG\" data-search=\"Κοῦμαι, ῶν, αἱ nome próprio geográfico feminino plural Cumas; antiga colônia grega na Campânia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κοῦμαι, ῶν, αἱ</td><td>nome próprio geográfico feminino plural</td><td>Cumas; antiga colônia grega na Campânia</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0208-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κορβᾶν</h1><div class=\"entry-meta\"><span>substantivo indeclinável; empréstimo hebraico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κορβᾶν</span>: indeclinável (os editores também escrevem -<span class=\"greek\">άν</span>; <span class=\"hebrew\" dir=\"rtl\">קָרְבָּן</span>), palavra hebraica explicada pela nota <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">δῶρον</span>, isto é, ‘que significa oferta’ (tradução correspondente à LXX, Lev 2:1, 4, 12, 13); algo consagrado como oferta a Deus, excluído do uso humano comum, oferta a Deus, corbã (compare Jos., Ant. 4, 73, sobre os nazireus: <span class=\"greek\">οἱ</span> <span class=\"greek\">κορβᾶν</span> <span class=\"greek\">αὑτοὺς</span> <span class=\"greek\">ὀνομάσαντες</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, <span class=\"greek\">δῶρον</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">σημαίνει</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Ἑλλήνων</span> <span class=\"greek\">γλῶτταν</span>, aqueles que se declararam ‘corbã’ para Deus, expressão que em grego significa ‘oferta’; C. Ap. 1, 167; quanto a inscrições hebraicas, veja Fitzmyer, abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:11</a> (compare <span class=\"greek\">κορβανᾶς</span>). Sobre esse tema, compare Philo, Spec. Leg. 2, 16f; Billerb. I 711ff; Dalman, Gramm.2 174, 3; HOrt, De verbintenissen met ‘Korban’: TT 37, 1903, 284–314; JHart, Corban: JQR 19, 1907, 615–50; HLaible, Korban: Allg. Ev.-Luth. Kirchenzeitung 54, 1921, 597ff; 613ff; MBlack, Aramaic Approach3, ’67, 139; HHommel, D. Wort Korban u. seine Verwandten: Philologus 98, ’54, 132–49; JFitzmyer, JBL 78, ’59, 60–65 = Essays on the Semitic Background of the NT ’71, 93–100; SZeitlin, JQR 53, ’62, 160–63.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κορβανᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; empréstimo semítico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κορβανᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\" dir=\"rtl\">קָרְבָּן</span>; aramaico <span class=\"hebrew\" dir=\"rtl\">קָרְבָּנָא</span>; veja B-D-F §58; = <span class=\"greek\">γαζοφυλακεῖον</span>): tesouraria do templo (Jos., Bell. 2, 175 <span class=\"greek\">ἱερὸς</span> <span class=\"greek\">θησαυρός</span>, <span class=\"greek\">καλεῖται</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κορβωνᾶς</span>, tesouro sagrado, chamado ‘corbanás’.—Dalman, Gramm.2 174, 3). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">βάλλειν</span>, colocar na tesouraria do templo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:6</a> (variantes de leitura <span class=\"greek\">κορβάν</span>, <span class=\"greek\">κορβονᾶν</span>; acerca da ficção jurídica, compare Mishnah: Erubin).—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κόρε, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κόρε</span>, <span class=\"greek\">ὁ</span>: indeclinável (editores também escrevem <span class=\"greek\">Κορέ</span>; <span class=\"hebrew\" dir=\"rtl\">קֹרַח</span>): Corá, chefe de uma revolta contra Moisés (Num 16; Sir 45:18; Philo, Fuga 145.—Jos., Ant. 4, 14ff: <span class=\"greek\">Κορῆς</span>, <span class=\"greek\">έου</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 11</a>; GJs 9:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κορέννυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κορέννυμι</span>: 1º aoristo <span class=\"greek\">ἐκορέσθην</span>; particípio perfeito passivo <span class=\"greek\">κεκορεσμένος</span> (Hom. e outros; Kaibel 314, 21f; ParJer; Jos., Ant. 2, 86; 10, 261): saciar, encher; na passiva, ficar saciado, ter o suficiente, com genitivo daquilo com que alguém fica saciado ou satisfeito (Hom. e outros; SibOr 3, 697). ⓐ Literalmente, <span class=\"greek\">κορεσθέντες</span> <span class=\"greek\">τροφῆς</span>, quando haviam comido o suficiente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:38</a>. ⓑ Figuradamente (Kaibel, veja acima; Appian, Hann. 27 §115, Bell. Civ. 1, 3, §10; Philo; Jos., Bell. 4, 314), com ironia (Straub 24): <span class=\"greek\">ἤδη</span> <span class=\"greek\">κεκορεσμένοι</span> <span class=\"greek\">ἐστέ</span>, já estais fartos, isto é, julgais possuir todo o alimento espiritual necessário, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:8</a>.—DELG s.v. <span class=\"greek\">κορε</span>-; Frisk s.v. <span class=\"greek\">κορρένυμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόρη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόρη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (significado primordial: ‘menina, jovem mulher’, Hom. e outros; TestSol 26:5; Just., A I, 27, 1; Tat. 19, 2; Ath.; em escala menor, ‘boneca’, Dio Chrys. 31, 153). A pequenina imagem refletida na íris deu origem ao uso de <span class=\"greek\">κ</span>. (= latim pupilla) para designar a ‘pupila’ do olho (autores trágicos, Hippocr. e outros; SIG 1169, 67, restaurado; LXX; Philo; Ps-Orph. [Denis 165, 22; Theosophien 181 §56]); pupila; em nossa literatura, empregada figuradamente acerca de algo muito estimado: <span class=\"greek\">ἀγαπᾶν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀφθαλμοῦ</span>, amar como a pupila do próprio olho = amar como pessoa querida, predileta ou ‘menina’ dos olhos, B 19:9 (compare Dt 32:10; Ps 16:8; Pr 7:2, todos com tradução do termo <span class=\"hebrew\" dir=\"rtl\">אִישׁוֹן</span>, ‘pequeno ser humano’; JosAs 25:5; 26:2).—A tradução inglesa ‘apple of the eye’ nas passagens veterotestamentárias supracitadas mistura as imagens, mas comunica o sentido de algo precioso (compare a tradução de Coverdale de Zech 2:8: ‘who so toucheth you, shal touche the aple of his owne eye’ [OED s.v. ‘apple’]).—Betz, SM 442 n. 141 (bibliografia). DELG s.v. 2 <span class=\"greek\">κόρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κορίνθιος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κορίνθιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>: o coríntio (autores trágicos, Hdt. e outros; inscrições; Ath. 17, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:8</a>, 27 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:11</a>; 1 Cl 47:6. Também no título de 1 e 2 Cor e de 1 e 2 Cl e nas subscrições de Ro, variante de leitura, e 1 Cl; 2 Cl 20:5 (subscrição) Funk; AcPlCor, como designação: <span class=\"greek\">ἡ</span> <span class=\"greek\">Κορινθίων</span> <span class=\"greek\">ἐκκλησία</span>, a igreja dos coríntios, 1:16.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κόρινθος, ου, ἡ</h1><div class=\"entry-meta\"><span>nome próprio geográfico feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κόρινθος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições, Philo, SibOr 3, 487 e outras passagens; Just., D. 1, 3; Ath. 17, 2): Corinto, cidade da Grécia no istmo do mesmo nome. Desde 27 a.C., capital da província senatorial da Acaia e sede do procônsul. A congregação cristã ali foi fundada por Paulo na chamada segunda viagem missionária, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:1</a>, 27 D; 19:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:1</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:20</a>; 1 Cl inscrição inicial; MPol 22:2; EpilMosq 5; AcPl Ha 6, 1f; AcPlCor 1:2; 2:1; <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Κ</span>., homens de Corinto, 2:26. Também na subscrição de Ro, variante de leitura, e de 1 Th.—ECurtius, Peloponnesos II 1852, 514ff; JCladder, Korinth 1923; OBroneer, BA 14, ’51, 78–96; Pauly-W. Suppl. IV 991–1036; VI 182ff, 1350f; Kl. Pauly III 301ff; BHHW II 988ff; Corinth, Results of Excavations Conducted by the American School of Classical Studies at Athens 1929ff; RCarpenter, Korinthos6 ’60; FJdeWaele, Corinth and St. Paul ’61; DESmith, The Egyptian Cults at Corinth: HTR 70, ’77, 201–31; GTheissen, The Social Setting of Pauline Christianity ’82 (tradução inglesa); JMurphy-O’Connor, St. Paul’s Corinth ’83 (referências), Corinth: ABD I 1134–39 (bibliografia adicional); PECS 240–43.—Veja a inscrição coríntia (Dssm., LO 12, 8 [LAE 16, 7]): [<span class=\"greek\">συνα</span>]<span class=\"greek\">γωγὴ</span> <span class=\"greek\">Ἑβρ</span>[<span class=\"greek\">αίων</span>] = Boffo, Iscrizioni no. 45 e bibliografia p. 361f. Strabo 8, 6, 20 sugere problemas de imoralidade associados a uma grande cidade portuária, mas suas referências à prostituição cultual, como na citação do provérbio <span class=\"greek\">οὐ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀνδρὸς</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">Κόρινθον</span> <span class=\"greek\">ἔσθ</span>’ <span class=\"greek\">ὁ</span> <span class=\"greek\">πλοῦς</span>, na mesma passagem (= Aristoph. Fgm. 902a; compare Ael. Aristid. 29, 17 K. = 40 p. 755 D.), dizem respeito aos tempos anteriores à dominação romana e foram empregadas sem a cautela devida para inferências a respeito da Corinto de Paulo.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κορνήλιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κορνήλιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (nome encontrado frequentemente: veja Diod S 11, 27, 1 [de um homem contemporâneo da batalha de Salamina, 480 a.C.]; 11, 86, 1; 14, 110, 1; índices de SIG e OGI; Preisigke, Namenbuch; Joseph.): Cornélio, centurião romano (<span class=\"greek\">ἑκατοντάρχης</span>) em Cesareia Marítima, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:1</a>, 3, 7, variante de leitura, 17, 22, 24f, 30f.—CBurchard, D. dreizehnte Zeuge ’70, 54 n. 11.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; unidade de medida</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (PSI 554, 14 [259 a.C.]; LXX; TestJud 9:8; Eupolemus, historiador judeu [II a.C.]: 723 Fgm. 2, 33 Jac. [em Eus., PE 9, 33]; Joseph.): medida hebraica para produtos secos (<span class=\"hebrew\" dir=\"rtl\">כֹּר</span>, ‘cor, kor’; HLewy, D. Semit. Fremdwörter im Griech. 1895, 116), medida de capacidade para cereais, farinha etc.; segundo Jos., Ant. 15, 314, = dez medimnos áticos, portanto aproximadamente 393 litros = cerca de 4 hectolitros, ou entre dez e doze bushels; medida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:7</a>.—Bibliografia em II <span class=\"greek\">βάτος</span>.—DELG s.v. 3 <span class=\"greek\">κόρος</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμέω</span>: imperfeito <span class=\"greek\">ἐκόσμουν</span>; futuro <span class=\"greek\">κοσμήσω</span>, LXX; 1º aoristo <span class=\"greek\">ἐκόσμησα</span>. Na passiva: aoristo <span class=\"greek\">ἐκοσμήθην</span>, LXX; perfeito, 3ª pessoa do singular, <span class=\"greek\">κεκόσμηται</span>, particípio <span class=\"greek\">κεκοσμημένος</span>; mais-que-perfeito, 3ª pessoa do singular, <span class=\"greek\">ἐκεκόσμητο</span> (veja <span class=\"greek\">κόσμος</span>; desde Hom.).</p>\n<p class=\"entry-text\">① Pôr em ordem de modo que algo pareça arrumado ou bem organizado; arrumar, pôr em boa ordem (Od. 7, 13; X., Cyr. 8, 2, 6; 6, 11; SIG 1038, 11 <span class=\"greek\">τράπεζαν</span>, uma mesa; PThéad 14, 18; Sir 29:26; 50:14; Just., A II, 5, 2 e outros; Tat. 12, 1; <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, a ordem do mundo, Mel., P. 82, 616): preparar, das lâmpadas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:7</a>. Na imagem de uma pessoa como casa da qual saiu um espírito possessivo: arrumada, preparada, posta em ordem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:25</a> (para outra nuance, veja 2a<span class=\"greek\">β</span> abaixo).</p>\n<p class=\"entry-text\">② Fazer algo adquirir aparência atraente pela ornamentação; adornar, decorar (Hes. e outros; LXX; SibOr 3, 426).</p>\n<p class=\"entry-text\">ⓐ Literalmente. <span class=\"greek\">α</span>. De pessoas, <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span>, alguém com alguma coisa (Diod S 17, 53, 3 <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅπλοις</span>, com armas [magníficas]; TestJud 13:5 <span class=\"greek\">ἐν</span> <span class=\"greek\">χρυσίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαργαρίταις</span>, com ouro e pérolas), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>. Na passiva (Xenophon Eph. 1, 2, 2 <span class=\"greek\">παρθένοι</span> <span class=\"greek\">κεκοσμημέναι</span>, virgens adornadas; TestSol 7:4 D; JosAs 4:2; Jos., Bell. 2, 444): <span class=\"greek\">νύμφη</span> <span class=\"greek\">κεκοσμημένη</span>, noiva adornada para o marido (Achilles Tat. 3, 7, 5; veja TestJud 12:1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:2</a>; compare Hv 4, 2, 1. De mulheres (POxy 1467, 5 <span class=\"greek\">γυναῖκες</span> <span class=\"greek\">κεκοσμημέναι</span>, mulheres enfeitadas): <span class=\"greek\">κοσμηθεῖσαι</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">μοιχείαν</span>, embelezadas para o adultério, ApcPt 9:24 (compare TestReub 5:5 <span class=\"greek\">κ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀπάτην</span> <span class=\"greek\">διανοίας</span>; TestJos 9:5).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. De coisas, <span class=\"greek\">τὶ</span>, algo; na passiva, o templo em Jerusalém: <span class=\"greek\">λίθοις</span> <span class=\"greek\">καλοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναθήμασιν</span> <span class=\"greek\">κεκόσμηται</span>, está adornado com belas pedras e ofertas votivas (SIG 725, 2f <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">ἀναθέμασι</span> <span class=\"greek\">κεκόσμηται</span>; 1100, 21f; 1050, 6; 2 Macc 9:16; TestSol 10:5; 25:9; Philo, Det. Pot. Ins. 20), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:5</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:19</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μνημεῖα</span>, adornar os sepulcros (compare X., Mem. 2, 2, 13; Jos., Ant. 14, 284 <span class=\"greek\">κ</span>. <span class=\"greek\">τάφον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:29</a>. <span class=\"greek\">δένδρα</span> <span class=\"greek\">καρποῖς</span> <span class=\"greek\">κεκοσμημένα</span>, árvores adornadas de frutos, Hs 9, 1, 10; 9, 28, 1. Essa interpretação foi também atribuída por alguns a <span class=\"greek\">οἶκος</span> <span class=\"greek\">κεκοσμημένος</span>, casa adornada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:25</a> (inscrição ZPE 29, ’78, 213–28, ln. 67 [I d.C.]; Philo, Deus Imm. 150; SIG 326, 15 <span class=\"greek\">κεκοσμημένην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span>; Ath. 26, 2).</p>\n<p class=\"entry-text\">ⓑ Figuradamente. <span class=\"greek\">α</span>. Tornar belo ou atraente interiormente, em sentido moral (de pessoas excepcionais, Pind., N. 6, 46 [78]; Thu. 2, 42, 2 <span class=\"greek\">αἱ</span> <span class=\"greek\">ἀρεταὶ</span> <span class=\"greek\">ἐκόσμησαν</span>, as virtudes adornaram; X., Cyr. 8, 1, 21; IGR IV, 288, 9 <span class=\"greek\">κεκόσμηκε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αὑτοῦ</span> <span class=\"greek\">βίον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καλλίστῃ</span> <span class=\"greek\">παρρησία</span>; IPriene 105, 36; TestAbr B 13 p. 117, 14 [Stone p. 82] <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλῇ</span> <span class=\"greek\">ὡραιότητι</span>): <span class=\"greek\">κ</span>. <span class=\"greek\">ἑαυτόν</span>, adornar a si mesmo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:5</a> (compare Epict. 3, 1, 26; Just., A I, 12, 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>.—Na passiva, com dativo daquilo que adorna (Diod S 16, 65, 2 <span class=\"greek\">ἀρεταῖς</span> <span class=\"greek\">κεκοσμημένος</span>; IK 30, 14, 4f; 3 Macc 6:1; Philo, Op. M. 139; Just., A II, 11, 4 <span class=\"greek\">κεκοσμημένον</span> <span class=\"greek\">τῷ</span> … <span class=\"greek\">κόσμῳ</span>): <span class=\"greek\">παντὶ</span> <span class=\"greek\">καλῷ</span> <span class=\"greek\">ἐκεκόσμητο</span>, estava ornado de tudo que é bom, MPol 13:2. <span class=\"greek\">καρποῖς</span>, de frutos, Dg 12:1. <span class=\"greek\">τ</span>. <span class=\"greek\">παναρέτῳ</span> <span class=\"greek\">πολιτείᾳ</span>, por uma conduta repleta de virtudes, 1 Cl 2:8. <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐνδόξῳ</span> <span class=\"greek\">ὀνόματι</span>, pelo nome glorioso, 43:2. Também com <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Sir 48:11 B, S, A <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγαπήσει</span> <span class=\"greek\">κεκοσμημένοι</span>; TestAbr A 11 p. 89, 19f [Stone p. 26] <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοιαύτῃ</span> <span class=\"greek\">δόξῃ</span> <span class=\"greek\">κοσμούμενος</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἀγαθοῖς</span>, com boas obras, 1 Cl 33:7; <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐντολαῖς</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, com os mandamentos de Jesus Cristo, IEph 9:2.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Adornar, dignificar, conferir prestígio a (Theognis 947 Diehl <span class=\"greek\">πατρίδα</span> <span class=\"greek\">κοσμήσω</span>, honrarei a pátria): <span class=\"greek\">ἵνα</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διδασκαλίαν</span> <span class=\"greek\">κοσμῶσιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, para que honrem a doutrina em todos os aspectos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:10</a>.—DELG s.v. <span class=\"greek\">κόσμος</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">κόσμος</span>; Aristot., Phys. 2, 4 p. 196a, 25 <span class=\"greek\">τοὐρανοῦ</span> <span class=\"greek\">τοῦδε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κοσμικῶν</span> <span class=\"greek\">πάντων</span>; Vett. Val. Index II; Lucian, Paras. 11 [oposto a <span class=\"greek\">ἀνθρώπινος</span>]; Ps.-Plutarch, Consol. ad Apoll. 34, Mor. 119e <span class=\"greek\">κοσμικὴ</span> <span class=\"greek\">διάταξις</span>; inscrições; PGM 4, 2533 <span class=\"greek\">τὰ</span> <span class=\"greek\">κοσμικὰ</span> <span class=\"greek\">πάντα</span>; TestAbr A 7 p. 84, 25 [Stone p. 16] <span class=\"greek\">τὸν</span> <span class=\"greek\">κοσμικὸν</span> <span class=\"greek\">βίον</span>; TestJos 17:8 <span class=\"greek\">κ</span>. … <span class=\"greek\">δόξαν</span>; Philo, Aet. M. 53; Jos., Bell. 4, 324; Tat. 12, 5 <span class=\"greek\">κ</span>. <span class=\"greek\">καταλήψεως</span>; Ath. 24, 5 <span class=\"greek\">κ</span>. <span class=\"greek\">σοφίας</span>; empréstimo no hebraico rabínico).</p>\n<p class=\"entry-text\">① Relativo à Terra como fenômeno físico, terrestre (TestJos. 17:8): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">κ</span>., o santuário terrestre (oposto ao celestial), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μυστήριον</span> <span class=\"greek\">ἐκκλησίας</span>, o mistério terrestre da igreja, D 11:11. <span class=\"greek\">κοσμικαὶ</span> <span class=\"greek\">βάσανοι</span>, tormentos terrestres, MPol 2:3.—Substantivado, <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ταῦτα</span>, essas coisas terrenas, 2 Cl 5:6 (compare Did., Gen. 149, 11).</p>\n<p class=\"entry-text\">② Relativo aos interesses predominantes na Terra, mundano, implicando hostilidade a Deus ou reprovabilidade moral: <span class=\"greek\">αἱ</span> <span class=\"greek\">κοσμικαὶ</span> <span class=\"greek\">ἐπιθυμίαι</span>, desejos mundanos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:12</a>; 2 Cl 17:3 (compare Iren.1, 16, 3 [Harv. I 164, 5]).—DELG s.v. <span class=\"greek\">κόσμος</span>. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόσμιος, (ία), ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόσμιος</span>, (<span class=\"greek\">ία</span>), <span class=\"greek\">ον</span> (veja <span class=\"greek\">κόσμος</span>; Aristoph., Pla. e outros; inscrições, papiros; Eccl 12:9; Just., 12, 5).</p>\n<p class=\"entry-text\">① Relativo a possuir características ou qualidades que despertam admiração ou agrado, expressando consideração elevada por pessoas; respeitável, honrado, aplicado a pessoas (Nicophon Com. [V/IV a.C.] 16; OGI 485, 3 <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">κόσμιον</span>, homem respeitável; Philo, Spec. Leg. 3, 89; Just.), junto de <span class=\"greek\">σώφρων</span> (IG IV2/1, 82, 27 [40/42 d.C.], inscrição honorífica de um homem), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:2</a>.</p>\n<p class=\"entry-text\">② Relativo àquilo que convém para obter aprovação, apropriado, empregado com substantivo impessoal, mas referindo-se a uma pessoa, cujo estatuto especial é provavelmente assinalado por essa expressão (compare IMagnMai 165, 6 <span class=\"greek\">κ</span>. <span class=\"greek\">ἀναστροφή</span>; 179, 4): <span class=\"greek\">ἐν</span> <span class=\"greek\">καταστολῇ</span> <span class=\"greek\">κ</span>., em vestimenta modesta (sobre mulheres, como Epict., Ench. 40; Dio Chrys. 5, 14; PSI 97, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>.—Substantivado, no plural, <span class=\"greek\">τὰ</span> <span class=\"greek\">κόσμια</span>, adornos, AcPl Ha 2, 21: <span class=\"greek\">κοσμί</span>[<span class=\"greek\">ων</span>]; veja observações do editor CSchmidt, p. 125.—DELG s.v. <span class=\"greek\">κόσμος</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμίως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμίως</span>: advérbio de <span class=\"greek\">κόσμιος</span> (Aristoph., Pla. e posteriores; inscrições, por exemplo IGR IV, 255, 9; Philo, Spec. Leg. 1, 153): relativo à conformidade com normas aceitas de decoro, modestamente, decorosamente, observando a compostura; sobre adorno pessoal, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:9</a>, variante de leitura (num jogo de palavras: <span class=\"greek\">κοσμίως</span>-<span class=\"greek\">κοσμεῖν</span>, ‘adornar-se’ ‘decorosamente’, em oposição ao consumo ostensivo).—DELG s.v. <span class=\"greek\">κόσμος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμοκράτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμοκράτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">κόσμος</span>, <span class=\"greek\">κρατέω</span>): governante do mundo (usado a respeito de deuses que governam o mundo [Orphica: Hymns 8, 11 Helios; 11, 11 Pan; Vett. Val. 170, 36 <span class=\"greek\">κ</span>. <span class=\"greek\">Ζεύς</span>; 171, 6; 314, 16 <span class=\"greek\">κ</span>. <span class=\"greek\">Ἥλιος</span>; PGM 4, 1599; 2198; 5, 400 e 17b, 1 <span class=\"greek\">Ἑρμῆς</span>; 13, 619 <span class=\"greek\">Σάραπις</span>] e do imperador Caracala [inscrição egípcia APF 2, 1903, 449 no. 83]. Depois, em geral, de seres espirituais que controlam partes do cosmos: Vett. Val. 278, 2; 360, 7; Iambl., Myst. 2, 9; 3, 10; TestSol; Iren. 1, 5, 4 [Harv. I 48, 2]; <span class=\"greek\">τὸν</span> <span class=\"greek\">διάβολον</span> …, <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κοσμοκράτωρα</span> <span class=\"greek\">καλοῦσι</span>, o diabo, a quem também chamam governante do mundo, 1, 5, 4 [Harv. I 47, 4].—FCumont, Compt. rend. Acad. des ins 1919, 313f; EPeterson, <span class=\"greek\">Εἷς</span> <span class=\"greek\">θεός</span> 1926, 238, 3. Também empréstimo no hebraico rabínico, por exemplo sobre o anjo da morte): de espíritos malignos (junto de <span class=\"greek\">ἀρχαί</span> e <span class=\"greek\">ἐξουσίαι</span>), <span class=\"greek\">οἱ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">τούτου</span>, os dominadores mundiais desta escuridão, isto é, os governantes deste mundo pecaminoso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a> (veja TestSol [18, 2] em Dibelius, Geisterwelt 230: espíritos comparecem perante Salomão e se denominam <span class=\"greek\">οἱ</span> <span class=\"greek\">κοσμοκράτορες</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σκότους</span> <span class=\"greek\">τούτου</span>. Sobre o assunto, veja Hdb. a respeito de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:31</a> e FDölger, D. Sonne d. Gerechtigkeit 1918, 49ff; GMacgregor, Principalities and Powers: ACPurdy Festschr. ’60, 88–104).—DELG s.v. <span class=\"greek\">κόσμος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμοπλανής, ῆτος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμοπλανής</span>, <span class=\"greek\">ῆτος</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">κόσμος</span>, <span class=\"greek\">πλανάω</span>): enganador do mundo, numa personificação apocalíptica do mal, D 16:4 (Harnack e Knopf leem <span class=\"greek\">κοσμοπλάνος</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κοσμοπλάνος</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κοσμοπλάνος</span>: veja <span class=\"greek\">κοσμοπλανής</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κόσμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κόσμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (desde Hom.).</p>\n<p class=\"entry-text\">① Aquilo que serve para embelezar por meio de decoração; adorno, ornamentação (desde Hom.; Diod S 20, 4, 5 <span class=\"greek\">τῶν</span> <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, os adornos das mulheres; OGI 531, 13; SIG 850, 10; IMaronIsis 41; PEleph 1, 4; PSI 240, 12 <span class=\"greek\">γυναικεῖον</span> <span class=\"greek\">κόσμον</span>, adornos femininos; LXX; TestJud 12:1; JosAs 2:6 e outras passagens; Philo, Migr. Abr. 97 <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">κ</span>.; Jos., Ant. 1, 250; 15, 5; Just., A II, 11, 4f): a respeito do vestuário das mulheres etc. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔξωθεν</span> … <span class=\"greek\">κόσμος</span>, o adorno exterior, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:3</a> (Vi. Hom. 4, sobre o adorno interior de uma mulher, ao lado de <span class=\"greek\">σωφροσύνη</span>, temperança; Crates, Ep. 9; Pythag., Ep. 11, 1; Plut., Mor. 141e; acerca do tema dos ornamentos externos, compare SIG 736, 15–26).</p>\n<p class=\"entry-text\">② Estado de boa ordem; disposição ordenada, ordem (Hom. e outros; veja HDiller, Die vorphilosophische Gebrauch von <span class=\"greek\">κ</span>. und <span class=\"greek\">κοσμεῖν</span>: BSnell Festschr., ’56, 47–60): <span class=\"greek\">μετὰ</span> <span class=\"greek\">κόσμου</span>, em ordem, Dg 12:9 (texto incerto; veja <span class=\"greek\">μετακόσμιος</span>).</p>\n<p class=\"entry-text\">③ A totalidade de tudo que existe aqui e agora; mundo, universo (ordenado), no uso filosófico (assim, segundo Plut., Mor. 886b, já em Pitágoras; seguramente em Heraclitus, Fgm. 66; Pla., Gorg. 508a, Phdr. 246c; Chrysipp., Fgm. 527 v. Arnim <span class=\"greek\">κόσμος</span> <span class=\"greek\">σύστημα</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτοις</span> <span class=\"greek\">περιεχομένων</span> <span class=\"greek\">φύσεων</span>, o universo é uma organização formada pelo céu, pela terra e pelas naturezas neles contidas. Igualmente Posidonius em Diog. L. 7, 138; Ps.-Aristot., De Mundo 2 p. 391b, 9ff; 2 e 4 Macc; Wsd; EpArist 254; Philo, Aet. M. 4; Jos., Ant. 1, 21; Test12Patr; SibOr 7, 123; AssMos Fgm. b Denis [=Tromp p. 272]; Just., A I, 20, 2 e outros; Ath. 19, 2 e outros; Orig., C. Cels. 4, 68, 14; Did., Gen. 36, 7; 137, 13.—O outro uso filosófico, em que <span class=\"greek\">κ</span>. denota o céu em oposição à terra, provavelmente não tem relevância para a nossa literatura [a menos que, talvez, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a> <span class=\"greek\">κ</span>. = ‘céu’?]). <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀέναος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σύστασις</span>, a constituição perpétua do universo, 1 Cl 60:1 (compare OGI 56, 48 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀέναον</span> <span class=\"greek\">κ</span>.). Sustentado por quatro elementos, Hv 3, 13, 3. <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἶναι</span>, antes que o mundo existisse, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:5</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">καταβολῆς</span> [<span class=\"greek\">κόσμου</span>], desde a fundação do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a>; 25:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a>; 9:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:8</a>; 17:8. Também <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">κ</span>., desde o princípio do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:21</a>, ou <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κτίσεως</span> <span class=\"greek\">κ</span>., desde a criação do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a>.—Em B 5:5, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">καταβ</span>. <span class=\"greek\">κ</span>. evidentemente significa ‘na fundação do mundo’ (veja Windisch, Hdb. ad loc.). <span class=\"greek\">πρὸ</span> <span class=\"greek\">καταβολῆς</span> <span class=\"greek\">κ</span>., antes da fundação do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:20</a> (sobre os usos com <span class=\"greek\">καταβολή</span>, veja essa entrada, 1). <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εἴδωλον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., nenhum ídolo tem existência real no universo (Twentieth Century NT), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:4</a>. Sobre a criação inteira, 3:22. <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ὅλος</span> = <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κτίσις</span>, o mundo inteiro = toda a criação (Sallust. 21 p. 36, 13; TestSol 5:7; TestJob 33:4), Hs 9, 2, 1; 9, 14, 5. <span class=\"greek\">φωστῆρες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span>, astros no universo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a> (veja acima). Especialmente sobre o universo como criação de Deus (Epict 4, 7, 6 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πεποίηκεν</span>, <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὅλον</span>, Deus fez todas as coisas, tanto as que estão no mundo como o próprio mundo inteiro; Wsd 9:9; 2 Macc 7:23 <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κτίστης</span>, o criador do mundo; 4 Macc 5:25; Just., A I, 59, 1 e outros; Ath. 8, 2 e outros): <span class=\"greek\">ὁ</span> <span class=\"greek\">ποιήσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., aquele que fez o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:24</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κτίστης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σύμπαντος</span> <span class=\"greek\">κ</span>., o criador de todo o universo, 1 Cl 19:2; <span class=\"greek\">ὁ</span> <span class=\"greek\">κτίσας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., aquele que criou o mundo, Hv 1, 3, 4; compare m 12, 4, 2. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κυριεύων</span>, aquele que governa o mundo inteiro, B 21:5. <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">εἶναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ἀγγέλων</span>, que o mundo nem sequer pertence a Deus, mas aos anjos, AcPlCor 1:15. Cristo é chamado <span class=\"greek\">παντὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κύριος</span>, Senhor de todo o mundo, 5:5; e o <span class=\"greek\">κ</span>. deve a existência à sua atuação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:10b</a>. O mundo foi criado em favor da igreja, Hv 2, 4, 1.—O universo, como o maior espaço imaginável, não consegue conter determinada coisa (Philo, Ebr. 32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:25</a>.</p>\n<p class=\"entry-text\">④ A totalidade dos seres situados acima do nível dos animais; o mundo, como em <span class=\"greek\">θέατρον</span> <span class=\"greek\">ἐγενήθημεν</span> (isto é, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀπόστολοι</span>) <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀγγέλοις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώποις</span>, tornamo-nos espetáculo para o mundo, tanto para anjos como para seres humanos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:9</a>. Aqui o mundo se divide em anjos e pessoas (compare a definição estoica de <span class=\"greek\">κόσμος</span> em Stob., Ecl. I p. 184, 8 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">σύστημα</span>, a comunidade constituída por deuses e homens; igualmente Epict 1, 9, 4.—Segundo Ocellus Luc. 37, final, o <span class=\"greek\">κ</span>. consiste na esfera do divino além da Lua e na esfera terrestre aquém da Lua).</p>\n<p class=\"entry-text\">⑤ O planeta Terra como lugar de habitação; mundo (SIG 814, 31 [67 d.C.], sobre Nero, <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">κύριος</span>, senhor de todo o mundo; o significado do aniversário de Augusto para o mundo, OGI 458, 40 [=IPriene 105]; 2 Macc 3:12; Jos., Ant. 9, 241; 10, 205; Orig., C. Cels. 4, 68).</p>\n<p class=\"entry-text\">ⓐ Em geral, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:15</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., os reinos do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:8</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., em todo o mundo, 26:13. Compare 13:38 (compare Hs 5, 5, 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:9</a>; Hs 9, 25, 2. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τούτου</span>, a luz deste mundo (o sol), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:9</a>. Em exagero retórico: <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καταγγέλλεται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμῳ</span>, a vossa fé é anunciada em todo o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a> (compare inscrição funerária egípcia APF 5, 1913, 169 no. 24, 8 <span class=\"greek\">ὧν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σωφροσύνη</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λελάληται</span>). Abraão como <span class=\"greek\">κληρονόμος</span> <span class=\"greek\">κόσμου</span>, herdeiro do mundo, 4:13.—Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:6</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀδελφότης</span>, a fraternidade existente no mundo (inteiro), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:9</a>. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span>, nosso Senhor assumiu a soberania sobre o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:15</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. (não na LXX, mas provavelmente o rabínico <span class=\"hebrew\" dir=\"rtl\">אֻמּוֹת</span> <span class=\"hebrew\" dir=\"rtl\">הָעוֹלָם</span> = humanidade à parte de Israel; Billerb. II 191; Dalman, Worte 144f), os não convertidos no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:30</a>. Nessa linha de desenvolvimento, <span class=\"greek\">κόσμος</span> isoladamente passa a designar o mundo politeísta não convertido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:12</a>, 15.—Outros mundos (terras) além do oceano, 1 Cl 20:8.—Muitas dessas passagens comportam a conotação de</p>\n<p class=\"entry-text\">ⓑ O mundo como morada da humanidade (como SibOr 1, 160). Também Hs 9, 17, 1f. <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., entrar no mundo pelo nascimento, 1 Cl 38:3. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξελθεῖν</span>, sair do mundo presente (Philo, Leg. All. 3, 5 <span class=\"greek\">ἔξω</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμου</span> <span class=\"greek\">φεύγειν</span>; veja <span class=\"greek\">ἐξέρχομαι</span> 5; compare Hippol., Ref. 5, 16, 7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:10b</a>; 2 Cl 8:3. <span class=\"greek\">γεννηθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., nascer no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:21</a>. <span class=\"greek\">ἕως</span> <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., enquanto estamos neste mundo, 2 Cl 8:2. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">εἰσφέρειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., nada trazer ao mundo (Philo, Spec. Leg. 1, 294 <span class=\"greek\">τὸν</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">εἰσενηνοχότα</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:7</a> (Pol 4:1). <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">πλάνοι</span> <span class=\"greek\">ἐξῆλθον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., muitos enganadores saíram pelo mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2J 7</a>.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμω</span> <span class=\"greek\">τούτῳ</span>, neste mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:25</a> (<span class=\"greek\">κ</span>. não precisa ser entendido aqui como entidade hostil a Deus, mas a transição para a nuance do sentido 7b, abaixo, é indicada pela expressão que se segue: <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span>, vida eterna). <span class=\"greek\">ἵνα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">προέλθῃ</span>, para que venha ao mundo, AcPlCor 2:6.</p>\n<p class=\"entry-text\">ⓒ Terra, mundo, em contraste com o céu (Dio Chrys. 19 [36], 59; Iren., 1, 4, 2 [Harv. I 35, 5]; Orig., C. Cels. 8, 15, 24), <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">τούτῳ</span>, neste mundo, 2 Cl 19:3.—Especialmente quando se menciona o Cristo preexistente, que veio de outro mundo para o <span class=\"greek\">κόσμος</span>. Assim, sobretudo em João (Bultmann, índice I <span class=\"greek\">κόσμος</span>): <span class=\"greek\">ἔρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. (<span class=\"greek\">τοῦτον</span>), vir para (este) mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:14</a>; 9:39; 11:27; 16:28a; 18:37; mais precisamente, também vir ao mundo como luz, 12:46; compare 1:9; 3:19. O envio de Jesus ao mundo, 3:17a; 10:36; 17:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:9</a>. Seu <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, estar no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:10a</a>; 9:5a; 17:12, variante de leitura. Deixar o mundo e voltar ao Pai, 13:1a; 16:28b. Compare 14:19; 17:11a. Sua realeza não é <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τούτου</span>, deste mundo, isto é, não deriva do mundo nem é condicionada por suas normas e avaliações, 18:36ab.—Também <span class=\"greek\">Χρ</span>. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἦλθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμον</span>, Cristo Jesus veio ao mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:15</a>; compare <span class=\"greek\">ἐπιστεύθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span>, foi crido no mundo (em oposição a <span class=\"greek\">ἀνελήμφθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δόξῃ</span>, foi recebido na glória), 3:16.—<span class=\"greek\">εἰσερχόμενος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., ao entrar no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:5</a>.</p>\n<p class=\"entry-text\">ⓓ O mundo exterior em contraste com o próprio lar, PtK 3 p. 15, 13; 19.</p>\n<p class=\"entry-text\">⑥ A humanidade em geral; o mundo (TestAbr B 8 p. 113, 11 [Stone p. 74]; ApcEsdr 3:6 p. 27, 14; SibOr 1, 189; Just., A I, 39, 3 e outros).</p>\n<p class=\"entry-text\">ⓐ Em geral: <span class=\"greek\">οὐαὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σκανδάλων</span>, ai da humanidade por causa das coisas que levam as pessoas a pecar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:7</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., a luz para a humanidade, 5:14; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:12</a>; 9:5. <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., o salvador do mundo, 4:42; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:14</a> (essa designação aparece em inscrições, especialmente com frequência para Adriano [WWeber, Untersuchungen z. Geschichte des Kaisers Hadrianus 1907, 225; 226; 229]).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:29</a>; 3:17b; 17:6.—<span class=\"greek\">κρίνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., julgar o mundo (SibOr 4, 184; TestAbr A 13 p. 92, 11 [Stone p. 32]; ApcMos 37), de Deus, de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:47a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:6</a>; B 4:12; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19</a>. Dos crentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:2ab</a> (compare Sallust. 21 p. 36, 13: as almas dos virtuosos, juntamente com os deuses, governarão o <span class=\"greek\">κόσμος</span> inteiro). Sobre Noé, <span class=\"greek\">δι</span>’ <span class=\"greek\">ἧς</span> (isto é, <span class=\"greek\">πίστεως</span>) <span class=\"greek\">κατέκρινεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., pela qual (fé) condenou o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:7</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἁμαρτία</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἰσῆλθεν</span>, o pecado entrou no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a>; igualmente <span class=\"greek\">θάνατος</span> <span class=\"greek\">εἰσῆλθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., a morte entrou no mundo, 1 Cl 3:4 (Wsd 2:24; 14:14). Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:27f</a>. <span class=\"greek\">περικαθάρματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., o refugo da humanidade, 4:13. Sobre pessoas antes da conversão: <span class=\"greek\">ἄθεοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., sem Deus no mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:12</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:12</a>; 5:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:2</a>; 4:1, 3. <span class=\"greek\">ἀρχαῖος</span> <span class=\"greek\">κόσμος</span>, as pessoas do mundo antigo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:5a</a>; compare o v. 5b; 3:6. De pessoas de mérito excepcional: <span class=\"greek\">ὧν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">ἄξιος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., de quem o mundo não era digno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>.—<span class=\"greek\">ὅλος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., o mundo inteiro, todos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:47</a> D; 1 Cl 5:7; compare <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., 59:2; <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., Hs 8, 3, 2. Igualmente <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> (compare Philo, De Prov. em Eus., PE 8, 14, 58): <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὀπίσω</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπῆλθεν</span>, o mundo foi atrás dele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:19</a>. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">λαλῶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., essas coisas digo ao mundo, 8:26; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., no mundo, 17:13; <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">παρρησίᾳ</span> <span class=\"greek\">λελάληκα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., falei abertamente ao mundo, 18:20; compare 7:4; 14:22. <span class=\"greek\">ἵνα</span> <span class=\"greek\">γνῷ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., para que o mundo saiba, 14:31; compare 17:23; <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πιστεύῃ</span>, para que o mundo creia, 17:21.</p>\n<p class=\"entry-text\">ⓑ Toda a humanidade, mas especialmente os crentes, como objeto do amor de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:16</a>, 17c; 6:33, 51; 12:47b.</p>\n<p class=\"entry-text\">⑦ O sistema da existência humana em seus diversos aspectos; o mundo.</p>\n<p class=\"entry-text\">ⓐ Como cenário das alegrias, posses, preocupações e sofrimentos terrenos (compare 4 Macc 8:23): <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὅλον</span> <span class=\"greek\">κερδῆσαι</span>, ganhar o mundo inteiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:25</a>; 2 Cl 6:2 (compare Procop. Soph., Ep. 137: toda a <span class=\"greek\">οἰκουμένη</span>, terra habitada, é posse insignificante quando comparada à <span class=\"greek\">ἀρετή</span>, virtude). <span class=\"greek\">τὰ</span> <span class=\"greek\">τερπνὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., as coisas agradáveis do mundo, IRo 6:1. <span class=\"greek\">οἱ</span> <span class=\"greek\">χρώμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καταχρώμενοι</span>, os que usam o mundo como se não fizessem uso dele, ou os que lidam com o mundo como se não tivessem feito negócios com ele, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:31a</a>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">βίον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., possuir bens deste mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:17</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>, os assuntos do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:33f</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:15f</a>. A última passagem conduz naturalmente às numerosas expressões (sobretudo em Paulo e João) em que</p>\n<p class=\"entry-text\">ⓑ O mundo, com tudo o que lhe pertence, aparece como aquilo que é hostil a Deus, isto é, perdido no pecado, completamente oposto a tudo o que é divino, arruinado e corrompido (Herm. Wr. 6, 4 [o <span class=\"greek\">κόσμος</span> é <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span>, a plenitude da maldade]; 13, 1 [<span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀπάτη</span>, o engano do mundo], em Stob. p. 428, 24 Sc.; En 48:7; TestIss 4:6; AscIs 3:25; Hdb., exc. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:10</a>; Bultmann ad loc.—Compare Sotades Maronita [III a.C.] 11 Diehl: o <span class=\"greek\">κόσμος</span> é injusto e hostil aos grandes homens), IMg 5:2; IRo 2:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">οὗτος</span>, este mundo (em contraste com o reino celestial), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:23</a>; 12:25, 31a; 13:1; 16:11; 18:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:19</a>; 5:10a; 7:31b; Hv 4, 3, 2ff; D 10:6; 2 Cl 5:1, 5; (em oposição a <span class=\"greek\">ὁ</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">αἰών</span>, a era santa), B 10:11. ‘Este mundo’ é governado pelo <span class=\"greek\">ἄρχων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τούτου</span>, príncipe deste mundo, o diabo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:31b</a>; 16:11; sem <span class=\"greek\">τούτου</span>, 14:30. Compare <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὅλος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πονηρῷ</span> <span class=\"greek\">κεῖται</span>, o mundo inteiro jaz sob o poder do maligno, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:19</a>; compare 4:4; também <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰὼν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τούτου</span>, a era deste mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:2</a> (veja <span class=\"greek\">αἰών</span> 4).—Os cristãos não devem ter participação nesse mundo de pecado e separação de Deus: em lugar de desejá-lo, IRo 7:1, deve-se <span class=\"greek\">ἄσπιλον</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., conservar-se incontaminado pelo mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>. <span class=\"greek\">ἀποφεύγειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μιάσματα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., escapar das contaminações do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:20</a>; compare 1:4 (veja <span class=\"greek\">ἀποφεύγω</span> 1).—Pol 5:3. <span class=\"greek\">ἡ</span> <span class=\"greek\">φιλία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἔχθρα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐστιν</span>, a amizade do mundo é inimizade contra Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:4a</a>; compare o v. 4b. Quando adotam tal atitude, os cristãos são naturalmente odiados pelo mundo, IRo 3:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:18</a>, 19ad; 17:14a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:13</a>, assim como seu Senhor foi odiado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:7</a>; 15:18; compare 1:10c; 14:17; 16:20.—Também em Paulo: Deus e o mundo aparecem em oposição: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. e <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span>, o espírito do mundo e o Espírito que vem de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:12</a>; <span class=\"greek\">σοφία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. e <span class=\"greek\">σοφία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, a sabedoria do mundo e a sabedoria de Deus, 1:20f. <span class=\"greek\">ἡ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">λύπη</span> e <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">λύπη</span>, tristeza segundo Deus e tristeza do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:10</a>. O mundo é condenado por Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:32</a>; contudo, é também objeto do plano divino de salvação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a>; compare 1 Cl 7:4; 9:4. O cristão está morto para o mundo: <span class=\"greek\">δι</span>’ <span class=\"greek\">οὗ</span> (isto é, <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>.) <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐσταύρωται</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">κόσμῳ</span>, por meio de Cristo o mundo foi crucificado para mim, e eu (fui crucificado) para o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:14</a>; compare a pergunta <span class=\"greek\">τί</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δογματίζεσθε</span>;, por que, como se vivêsseis no mundo, vos sujeitais a decretos?, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:20b</a>. Para <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κ</span>., elementos do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>, 20a, veja <span class=\"greek\">στοιχεῖον</span>.—O emprego de <span class=\"greek\">κ</span>. nesse sentido desenvolve-se ainda mais em João. O <span class=\"greek\">κ</span>. está em oposição a Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:15f</a>, e por isso é incapaz de conhecê-lo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:25</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:5</a>, e é excluído da intercessão de Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:9</a>; suas opiniões são refutadas pelo Paráclito, 16:8. Nem o próprio Cristo, 17:14c, 16b; 14:27, nem os seus, 15:19b; 17:14b, 16a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:1</a>, pertencem de algum modo ao ‘mundo’. Antes, Cristo os escolheu ‘do mundo’, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:19c</a>, embora por enquanto ainda devam viver ‘no mundo’, 17:11b; compare 13:1b; 17:15, 18b. Toda a aflição que devem suportar por isso, 16:33a, nada representa em comparação com a convicção vitoriosa de que Cristo (e os crentes com ele) venceu ‘o mundo’, v. 33b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4f</a>, e de que o mundo está destinado a passar, 2:17 (TestJob 33:4; Kephal. I 154, 21: o <span class=\"greek\">κόσμος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, mundo da carne, passará).</p>\n<p class=\"entry-text\">⑧ O aspecto coletivo de uma entidade; totalidade, soma completa (SIG 850, 10 <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span>, a totalidade das obras [mas veja 1 acima]; Pr 17:6a): <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">καθίσταται</span>, a língua torna-se (ou revela ser) a soma total da iniquidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6</a> (assim, aproximadamente, Meinertz; FHauck.—MDibelius, Windisch e ASchlatter encontram aqui o sentido 7b, ao passo que ACarr, Exp. 7th ser., 8, 1909, 318ff, considera o sentido 1). <span class=\"greek\">Χρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σῳζομένων</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">παθόντα</span>, Cristo, que sofreu ou morreu (veja <span class=\"greek\">πάσχω</span> 3a<span class=\"greek\">α</span>) pela salvação da totalidade dos que são salvos, MPol 17:2.—FBytomski, D. genet. Entwicklung des Begriffes <span class=\"greek\">κόσμος</span> in d. Hl. Schrift: Jahrb. für Philos. und spekul. Theol. 25, 1911, 180–201; 389–413 (apenas o AT); CSchneider, Pls u. d. Welt: <span class=\"greek\">Αγγελος</span> IV ’32, 11–47; EvSchrenck, Der Kosmos-Begriff bei Joh.: Mitteilungen u. Nachrichten f. d. evang. Kirche in Russland 51, 1895, 1–29; RLöwe, Kosmos u. Aion ’35; RBultmann, D. Verständnis v. Welt u. Mensch im NT u. im Griechentum: ThBl 19, ’40, 1–14; GBornkamm, Christus u. die Welt in der urchr. Botschaft: ZTK 47, ’50, 212–26; ALesky, Kosmos ’63; RVölkl, Christ u. Welt nach dem NT ’61; GJohnston, <span class=\"greek\">οἰκουμένη</span> and <span class=\"greek\">κ</span>. in the NT: NTS 10, ’64, 352–60; NCassem, ibid. 19, ’72/73, 81–91; RBratcher, BT 31, ’80, 430–34.—B. 13; 440. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κούαρτος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κούαρτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (os editores também escrevem <span class=\"greek\">Κουᾶρτος</span>; sobre o acento, veja B-D-F §41, 2; 3; Rob. 235f): Quarto, cristão sobre quem nada mais se sabe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:23</a>; subscrição de 1 Cor, variante de leitura.—LGPN I.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κουμ</h1><div class=\"entry-meta\"><span>forma aramaica; imperativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κουμ</span> (manuscritos e editores também apresentam <span class=\"greek\">κούμ</span>, <span class=\"greek\">κοῦμ</span>, <span class=\"greek\">κουμί</span>): forma mesopotâmica do imperativo <span class=\"hebrew\" dir=\"rtl\">קוּם</span>, para o qual o aramaico palestinense tem <span class=\"hebrew\" dir=\"rtl\">קוּמִי</span>, levanta-te, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:41</a> (Wlh. ad loc.).—TRE III 609.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0208-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κοῦμαι, ῶν, αἱ</h1><div class=\"entry-meta\"><span>nome próprio geográfico feminino plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κοῦμαι</span>, <span class=\"greek\">ῶν</span>, <span class=\"greek\">αἱ</span> (forma grega: Paradoxogr. Flor. 28; Ptolem. 3, 1, 6): Cumas, cidade na Campânia, Itália, não distante de Nápoles; antiga colônia grega, célebre por sua Sibila (sobre Cumas como residência da Sibila, veja MDibelius, Hdb., excursus a Hv 2, 4, 1). Hv 1, 1, 3; 2, 1, 1.—PECS 251–52.</p></section></article>"};
